theorem bennett_step (g : α → γ) (h : γ → β) (z : α × γ × β) :
    let s1 : α × γ × β := (z.1, z.2.1 + g z.1, z.2.2)
    let s2 : α × γ × β := (s1.1, s1.2.1, s1.2.2 + h s1.2.1)
    let s3 : α × γ × β := (s2.1, s2.2.1 - g s2.1, s2.2.2)
    s3 = bennettStep g h z

